package com.confirmspellbook;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class PluginLauncher
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(ConfirmSpellbookPlugin.class);
		RuneLite.main(args);
	}
}

package com.confirmspellbook;

import java.util.EnumMap;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.EnumID;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.game.ItemManager;

/** Reads the current loadout on the client thread; returned snapshots need no further client reads. */
@Singleton
public class PlayerLoadout
{
    private static final int[] RUNE_POUCH_TYPE_VARBITS = {
        VarbitID.RUNE_POUCH_TYPE_1, VarbitID.RUNE_POUCH_TYPE_2, VarbitID.RUNE_POUCH_TYPE_3,
        VarbitID.RUNE_POUCH_TYPE_4, VarbitID.RUNE_POUCH_TYPE_5, VarbitID.RUNE_POUCH_TYPE_6
    };
    private static final int[] RUNE_POUCH_QUANTITY_VARBITS = {
        VarbitID.RUNE_POUCH_QUANTITY_1, VarbitID.RUNE_POUCH_QUANTITY_2, VarbitID.RUNE_POUCH_QUANTITY_3,
        VarbitID.RUNE_POUCH_QUANTITY_4, VarbitID.RUNE_POUCH_QUANTITY_5, VarbitID.RUNE_POUCH_QUANTITY_6
    };
    private static final Set<Integer> RUNE_POUCH_ITEM_IDS = Set.of(
        ItemID.BH_RUNE_POUCH, ItemID.BH_RUNE_POUCH_TROUVER,
        ItemID.DIVINE_RUNE_POUCH, ItemID.DIVINE_RUNE_POUCH_TROUVER);
    private static final ThrallRune[] RUNES = ThrallRune.values();

    @Inject
    private Client client;

    @Inject
    private ItemManager itemManager;

    public static boolean isRunePouchVarbit(int varbitId)
    {
        for (int slot = 0; slot < RUNE_POUCH_TYPE_VARBITS.length; slot++)
        {
            if (RUNE_POUCH_TYPE_VARBITS[slot] == varbitId || RUNE_POUCH_QUANTITY_VARBITS[slot] == varbitId)
            {
                return true;
            }
        }
        return false;
    }

    /** One scan of each container, one enum lookup, and one read of each pouch slot. */
    public Snapshot snapshot()
    {
        Readout readout = readContainers(true);
        if (readout.pouch)
        {
            readRunePouch(readout);
        }
        return new Snapshot(readout.carriedItems(), readout.runes);
    }

    /** Lightweight event observation, without reading rune totals or pouch varbits. */
    public CarriedItems carriedItems()
    {
        return readContainers(false).carriedItems();
    }

    private Readout readContainers(boolean includeRunes)
    {
        Readout readout = new Readout();
        readContainer(client.getItemContainer(InventoryID.INVENTORY), false, includeRunes, readout);
        readContainer(client.getItemContainer(InventoryID.EQUIPMENT), true, includeRunes, readout);
        return readout;
    }

    private void readContainer(ItemContainer container, boolean equipment, boolean includeRunes, Readout readout)
    {
        if (container == null)
        {
            return;
        }
        Item[] items = container.getItems();
        for (int slot = 0; slot < items.length; slot++)
        {
            Item item = items[slot];
            if (item == null || item.getId() < 0 || item.getQuantity() <= 0)
            {
                continue;
            }
            int canonicalId = itemManager.canonicalize(item.getId());
            readout.book |= canonicalId == ItemID.BOOK_OF_THE_DEAD;
            readout.pouch |= RUNE_POUCH_ITEM_IDS.contains(canonicalId);
            if (!includeRunes)
            {
                continue;
            }
            if (!equipment)
            {
                // Use the actual id for runes: noted runes cannot be cast from.
                readout.addRunes(item.getId(), item.getQuantity());
            }
            else if (slot == EquipmentInventorySlot.WEAPON.getSlotIdx()
                || slot == EquipmentInventorySlot.SHIELD.getSlotIdx())
            {
                for (ThrallRune rune : RUNES)
                {
                    if (rune.isInfiniteSource(canonicalId))
                    {
                        readout.runes.put(rune, Integer.MAX_VALUE);
                    }
                }
            }
        }
    }

    private void readRunePouch(Readout readout)
    {
        EnumComposition runeEnum = client.getEnum(EnumID.RUNEPOUCH_RUNE);
        if (runeEnum == null)
        {
            return;
        }
        for (int slot = 0; slot < RUNE_POUCH_TYPE_VARBITS.length; slot++)
        {
            int runeType = client.getVarbitValue(RUNE_POUCH_TYPE_VARBITS[slot]);
            int quantity = client.getVarbitValue(RUNE_POUCH_QUANTITY_VARBITS[slot]);
            if (runeType != 0 && quantity > 0)
            {
                readout.addRunes(runeEnum.getIntValue(runeType), quantity);
            }
        }
    }

    private static final class Readout
    {
        private boolean book;
        private boolean pouch;
        private final Map<ThrallRune, Integer> runes = new EnumMap<>(ThrallRune.class);

        private void addRunes(int itemId, int quantity)
        {
            for (ThrallRune rune : RUNES)
            {
                if (rune.isSatisfiedByRune(itemId))
                {
                    long total = (long) runes.getOrDefault(rune, 0) + quantity;
                    runes.put(rune, (int) Math.min(Integer.MAX_VALUE, total));
                }
            }
        }

        private CarriedItems carriedItems()
        {
            return new CarriedItems(book, pouch);
        }
    }

    public static final class CarriedItems
    {
        private final boolean book;
        private final boolean pouch;

        CarriedItems(boolean book, boolean pouch)
        {
            this.book = book;
            this.pouch = pouch;
        }

        public boolean hasBookOfTheDead()
        {
            return book;
        }

        public boolean hasRunePouch()
        {
            return pouch;
        }
    }

    public static final class Snapshot
    {
        private final CarriedItems carriedItems;
        private final Map<ThrallRune, Integer> runes;

        Snapshot(CarriedItems carriedItems, Map<ThrallRune, Integer> runes)
        {
            this.carriedItems = carriedItems;
            this.runes = new EnumMap<>(ThrallRune.class);
            this.runes.putAll(runes);
        }

        public CarriedItems getCarriedItems()
        {
            return carriedItems;
        }

        public int castsAvailable(ThrallTier tier)
        {
            return tier.castsAvailable(rune -> runes.getOrDefault(rune, 0));
        }
    }
}

package com.confirmspellbook;

import java.awt.event.MouseEvent;
import javax.inject.Inject;
import net.runelite.client.input.MouseAdapter;

/** Consumes the entire Confirm click so it cannot also interact with the game underneath. */
public class ConfirmMouseListener extends MouseAdapter
{
    private final ConfirmSpellbookOverlay overlay;
    private boolean confirming;

    @Inject
    ConfirmMouseListener(ConfirmSpellbookOverlay overlay)
    {
        this.overlay = overlay;
    }

    @Override
    public MouseEvent mousePressed(MouseEvent event)
    {
        if (event.getButton() == MouseEvent.BUTTON1)
        {
            // Leave Alt-dragging to RuneLite's overlay positioning controls.
            confirming = !event.isConsumed() && !event.isAltDown() && overlay.confirmAt(event.getPoint());
            if (confirming)
            {
                event.consume();
            }
        }
        return event;
    }

    @Override
    public MouseEvent mouseReleased(MouseEvent event)
    {
        if (confirming && event.getButton() == MouseEvent.BUTTON1)
        {
            event.consume();
        }
        return event;
    }

    @Override
    public MouseEvent mouseClicked(MouseEvent event)
    {
        if (confirming && event.getButton() == MouseEvent.BUTTON1)
        {
            event.consume();
            confirming = false;
        }
        return event;
    }

    void reset()
    {
        confirming = false;
    }
}

package com.confirmspellbook;

import com.google.inject.Provides;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.ChatMessageType;
import net.runelite.api.GameState;
import net.runelite.api.InventoryID;
import net.runelite.api.Skill;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.StatChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.Notifier;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.config.Notification;
import net.runelite.client.config.RuneLiteConfig;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.input.KeyManager;
import net.runelite.client.input.MouseManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientUI;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.HotkeyListener;

@Slf4j
@PluginDescriptor(
    name = "Confirm Spellbook",
    description = "Confirm your spellbook after bank withdrawals and check for missing thrall supplies",
    tags = {"confirm", "spellbook", "ancient", "ancients", "ancient magicks", "standard", "lunar", "arceuus", "thrall", "thralls", "book of the dead", "rune pouch", "runes", "magic", "reminder", "warning", "loadout", "endrit"}
)
public class ConfirmSpellbookPlugin extends Plugin
{
    private static final int ARCEUUS_SPELLBOOK = 3;

    @Inject
    private Client client;

    @Inject
    private ConfirmSpellbookConfig config;

    @Inject
    private OverlayManager overlayManager;

    @Inject
    private ConfirmSpellbookOverlay overlay;

    @Inject
    private Notifier notifier;

    @Inject
    private ChatMessageManager chatMessageManager;

    @Inject
    private RuneLiteConfig runeLiteConfig;

    @Inject
    private ClientUI clientUI;

    @Inject
    private KeyManager keyManager;

    @Inject
    private MouseManager mouseManager;

    @Inject
    private ConfirmMouseListener confirmMouseListener;

    @Inject
    private ClientThread clientThread;

    @Inject
    private PlayerLoadout loadout;

    private boolean hasArceuusSpellbook = false;
    private boolean hasSufficientThrallRunes = false;
    private boolean hasBookOfTheDead = false;
    private boolean hasRunePouch = false;
    private boolean carriedItemsKnown = false;
    private boolean checksArmed = false;
    private boolean acknowledgmentNeedsReset = false;
    private volatile boolean arceuusSpellbookConfirmed = false;
    private int spellbook = -1;
    private int warningSpellbook = -1;
    private volatile boolean warningShown = false;
    private volatile MissingCondition currentMissingCondition = MissingCondition.NONE;
    private volatile long warningVersion = 0;
    private boolean stateDirty = true;
    private volatile boolean active;
    private int magicLevel = 1;

    private final HotkeyListener hotkeyListener = new HotkeyListener(() -> config.hideReminderHotkey())
    {
        @Override
        public void hotkeyPressed()
        {
            confirmWarning(warningVersion);
        }
    };

    @Override
    protected void startUp() throws Exception
    {
        active = true;
        clearWarning();
        overlayManager.add(overlay);
        keyManager.registerKeyListener(hotkeyListener);
        confirmMouseListener.reset();
        mouseManager.registerMouseListener(confirmMouseListener);
        clientThread.invokeLater(this::refreshPlayerState);
        log.info("Confirm Spellbook started!");
    }

    @Override
    protected void shutDown() throws Exception
    {
        active = false;
        clearWarning();
        overlayManager.remove(overlay);
        keyManager.unregisterKeyListener(hotkeyListener);
        mouseManager.unregisterMouseListener(confirmMouseListener);
        confirmMouseListener.reset();
        log.info("Confirm Spellbook stopped!");
    }

    @Subscribe
    public void onVarbitChanged(VarbitChanged event)
    {
        // The server can update the backing varp without emitting an individual varbit id.
        if (event.getVarpId() >= 0 || event.getVarbitId() == VarbitID.SPELLBOOK
            || PlayerLoadout.isRunePouchVarbit(event.getVarbitId()))
        {
            stateDirty = true;
        }
    }

    @Subscribe
    public void onGameTick(GameTick event)
    {
        if (stateDirty)
        {
            refreshPlayerState();
        }
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        if (event.getGameState() == GameState.LOGGED_IN)
        {
            stateDirty = true;
        }
        else if (event.getGameState() == GameState.LOGIN_SCREEN
            || event.getGameState() == GameState.HOPPING
            || event.getGameState() == GameState.CONNECTION_LOST)
        {
            clearWarning();
        }
    }

    @Subscribe
    public void onItemContainerChanged(ItemContainerChanged event)
    {
        if (isInventoryOrEquipment(event.getContainerId()))
        {
            if (active && client.getGameState() == GameState.LOGGED_IN)
            {
                // Preserve item transitions even when deposit and withdrawal occur before the next tick.
                checkCarriedItems(loadout.carriedItems(), true);
            }
            stateDirty = true;
        }
    }

    // Magic experience arrives constantly in combat, so only a level change can move the auto tier.
    @Subscribe
    public void onStatChanged(StatChanged event)
    {
        boolean magicLevelChanged = event.getSkill() == Skill.MAGIC && event.getLevel() != magicLevel;
        if (magicLevelChanged)
        {
            stateDirty = true;
        }
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        if (!ConfirmSpellbookConfig.GROUP.equals(event.getGroup()))
        {
            return;
        }

        clientThread.invokeLater(this::refreshPlayerState);
    }

    private void refreshPlayerState()
    {
        if (!active || client.getGameState() != GameState.LOGGED_IN)
        {
            return;
        }

        stateDirty = false;
        if (!checksArmed)
        {
            // Login/startup only establishes what is already carried, without reading pouch runes.
            checkCarriedItems(loadout.carriedItems(), false);
            return;
        }
        magicLevel = client.getRealSkillLevel(Skill.MAGIC);
        checkSpellbook();
        PlayerLoadout.Snapshot snapshot = loadout.snapshot();
        checkThrallRunes(snapshot);
        checkCarriedItems(snapshot.getCarriedItems(), false);
        evaluateWarningState();
    }

    private boolean isInventoryOrEquipment(int containerId)
    {
        return containerId == InventoryID.INVENTORY.getId()
            || containerId == InventoryID.EQUIPMENT.getId();
    }

    private void checkSpellbook()
    {
        int currentSpellbook = client.getVarbitValue(VarbitID.SPELLBOOK);
        if (spellbook != currentSpellbook)
        {
            arceuusSpellbookConfirmed = false;
        }
        spellbook = currentSpellbook;
        hasArceuusSpellbook = spellbook == ARCEUUS_SPELLBOOK;
    }

    private void checkThrallRunes(PlayerLoadout.Snapshot snapshot)
    {
        ThrallTier tier = ThrallTier.highestCastableAt(magicLevel);
        hasSufficientThrallRunes = snapshot.castsAvailable(tier) >= 1;
    }

    private void checkCarriedItems(PlayerLoadout.CarriedItems carriedItems, boolean containerEvent)
    {
        boolean bookPresent = carriedItems.hasBookOfTheDead();
        boolean pouchPresent = carriedItems.hasRunePouch();
        if (carriedItemsKnown && ((!hasBookOfTheDead && bookPresent) || (!hasRunePouch && pouchPresent)))
        {
            if (!checksArmed && containerEvent)
            {
                Widget bank = client.getWidget(InterfaceID.Bankmain.ITEMS);
                checksArmed = bank != null && !bank.isHidden();
            }
            acknowledgmentNeedsReset = true;
            arceuusSpellbookConfirmed = false;
            // A click queued for the previous loadout must not acknowledge the new one.
            warningVersion++;
            overlay.clearConfirmTarget();
        }
        // The book itself confirms Arceuus. If it is removed later, ask again.
        if (bookPresent || !pouchPresent)
        {
            arceuusSpellbookConfirmed = false;
        }
        hasBookOfTheDead = bookPresent;
        hasRunePouch = pouchPresent;
        carriedItemsKnown = true;
    }

    private void evaluateWarningState()
    {
        // Confirm the spellbook first; carrying the book already confirms Arceuus.
        boolean checkCarriedItems = config.checkCarriedRunePouch();
        if (!checkCarriedItems || !config.notifyOnWrongSpellbook())
        {
            arceuusSpellbookConfirmed = false;
        }
        MissingCondition missingCondition;
        if (checkCarriedItems && (hasBookOfTheDead || hasRunePouch)
            && (!hasArceuusSpellbook || (!hasBookOfTheDead && !arceuusSpellbookConfirmed))
            && config.notifyOnWrongSpellbook())
        {
            missingCondition = MissingCondition.SPELLBOOK_CONFIRMATION;
        }
        else if (checkCarriedItems && hasRunePouch && !hasSufficientThrallRunes && config.notifyOnMissingRunes())
        {
            missingCondition = MissingCondition.THRALL_RUNES;
        }
        else
        {
            missingCondition = countConditionsMet() == 2 ? determineMissingCondition() : MissingCondition.NONE;
        }

        if (!isConditionNotificationEnabled(missingCondition))
        {
            missingCondition = MissingCondition.NONE;
        }

        // Keep the condition after Confirm, so unrelated inventory updates cannot re-show it.
        boolean rearmAcknowledgedWarning = acknowledgmentNeedsReset && !warningShown;
        acknowledgmentNeedsReset = false;
        int nextWarningSpellbook = missingCondition == MissingCondition.SPELLBOOK_CONFIRMATION ? spellbook : -1;
        if (missingCondition == currentMissingCondition && nextWarningSpellbook == warningSpellbook
            && !rearmAcknowledgedWarning)
        {
            return;
        }

        currentMissingCondition = missingCondition;
        warningSpellbook = nextWarningSpellbook;
        warningVersion++;
        warningShown = missingCondition != MissingCondition.NONE;
        overlay.clearConfirmTarget();
        if (warningShown)
        {
            sendNotification();
        }
    }

    private int countConditionsMet()
    {
        int count = 0;
        if (hasArceuusSpellbook) count++;
        if (hasSufficientThrallRunes) count++;
        if (hasBookOfTheDead) count++;
        return count;
    }

    private boolean isConditionNotificationEnabled(MissingCondition condition)
    {
        switch (condition)
        {
            case BOOK_OF_THE_DEAD:
                return config.notifyOnMissingBook();
            case THRALL_RUNES:
                return config.notifyOnMissingRunes();
            case SPELLBOOK_CONFIRMATION:
                return config.notifyOnWrongSpellbook();
            default:
                return false;
        }
    }

    private MissingCondition determineMissingCondition()
    {
        if (!hasBookOfTheDead)
        {
            return MissingCondition.BOOK_OF_THE_DEAD;
        }

        if (!hasArceuusSpellbook)
        {
            return MissingCondition.SPELLBOOK_CONFIRMATION;
        }

        if (!hasSufficientThrallRunes)
        {
            return MissingCondition.THRALL_RUNES;
        }

        return MissingCondition.NONE;
    }

    public MissingCondition getCurrentMissingCondition()
    {
        return currentMissingCondition;
    }

    public String getReminderLongText()
    {
        if (currentMissingCondition == MissingCondition.SPELLBOOK_CONFIRMATION)
        {
            return "Confirm spellbook : " + getSpellbookName();
        }
        return currentMissingCondition.getLongText();
    }

    public String getReminderShortText()
    {
        if (currentMissingCondition == MissingCondition.SPELLBOOK_CONFIRMATION)
        {
            return getSpellbookName() + "!";
        }
        return currentMissingCondition.getShortText();
    }

    private void sendNotification()
    {
        Notification notification = config.notification();
        if (!notification.isEnabled())
        {
            return;
        }

        if (!notification.isOverride() || !notification.isInitialized())
        {
            // Resolve inherited settings before disabling the default chat copy.
            notification = new Notification(true, true, true,
                runeLiteConfig.enableTrayNotifications(), notification.getTrayIconType(),
                runeLiteConfig.notificationRequestFocus(), runeLiteConfig.notificationSound(), null,
                runeLiteConfig.notificationVolume(), runeLiteConfig.notificationTimeout(),
                runeLiteConfig.enableGameMessageNotification(), runeLiteConfig.flashNotification(),
                runeLiteConfig.notificationFlashColor(), runeLiteConfig.sendNotificationsWhenFocused());
        }

        String message = getReminderLongText();
        // Check focus before Notifier can bring the game window to the foreground.
        boolean sendChat = notification.isGameMessage() && client.getGameState() == GameState.LOGGED_IN
            && (notification.isSendWhenFocused() || !clientUI.isFocused());
        notifier.notify(notification.withGameMessage(false), message);
        if (sendChat)
        {
            chatMessageManager.queue(QueuedMessage.builder()
                .type(ChatMessageType.CONSOLE)
                .runeLiteFormattedMessage(new ChatMessageBuilder()
                    .append(config.chatNotificationColor(), message).build())
                .build());
        }
    }

    public long getWarningVersion()
    {
        return warningVersion;
    }

    private String getSpellbookName()
    {
        switch (warningSpellbook)
        {
            case 0:
                return "Standard";
            case 1:
                return "Ancients";
            case 2:
                return "Lunar";
            case ARCEUUS_SPELLBOOK:
                return "Arceuus";
            default:
                return "Unknown (" + warningSpellbook + ")";
        }
    }

    // Both mouse events and hotkeys arrive off the client thread.
    public void confirmWarning(long expectedVersion)
    {
        clientThread.invokeLater(() ->
        {
            if (active && warningShown && warningVersion == expectedVersion)
            {
                warningShown = false;
                acknowledgmentNeedsReset = false;
                overlay.clearConfirmTarget();
                if (currentMissingCondition == MissingCondition.SPELLBOOK_CONFIRMATION
                    && warningSpellbook == ARCEUUS_SPELLBOOK)
                {
                    // Confirming the spellbook must not dismiss a separate supply warning.
                    arceuusSpellbookConfirmed = true;
                    evaluateWarningState();
                }
            }
        });
    }

    private void clearWarning()
    {
        hasBookOfTheDead = false;
        hasRunePouch = false;
        carriedItemsKnown = false;
        checksArmed = false;
        acknowledgmentNeedsReset = false;
        arceuusSpellbookConfirmed = false;
        warningShown = false;
        currentMissingCondition = MissingCondition.NONE;
        warningSpellbook = -1;
        warningVersion++;
        stateDirty = true;
        overlay.clearConfirmTarget();
    }

    public boolean shouldShowWarning()
    {
        return warningShown;
    }

    public boolean shouldShowConfirmButton()
    {
        return warningShown && (currentMissingCondition == MissingCondition.SPELLBOOK_CONFIRMATION
            || (currentMissingCondition == MissingCondition.BOOK_OF_THE_DEAD && arceuusSpellbookConfirmed));
    }

    @Provides
    ConfirmSpellbookConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(ConfirmSpellbookConfig.class);
    }
}

package com.confirmspellbook;

import java.util.Arrays;
import java.util.Collections;
import java.util.Comparator;
import java.util.EnumMap;
import java.util.Map;
import java.util.function.ToIntFunction;

/**
 * A tier of Resurrect Thrall spells. Ghost, skeleton and zombie thralls of the same tier share a
 * Magic requirement and a rune cost, so the tier alone determines what the player needs to carry.
 */
public enum ThrallTier
{
	LESSER("Lesser", 38, ThrallRune.AIR, ThrallRune.MIND),
	SUPERIOR("Superior", 57, ThrallRune.EARTH, ThrallRune.DEATH),
	GREATER("Greater", 76, ThrallRune.FIRE, ThrallRune.BLOOD);

	private static final class RunesPerCast
	{
		private static final int ELEMENTAL = 10;
		private static final int CATALYTIC = 5;
		private static final int COSMIC = 1;
	}

	private final String displayName;
	private final int magicLevel;
	private final Map<ThrallRune, Integer> runesPerCast;

	ThrallTier(String displayName, int magicLevel, ThrallRune elemental, ThrallRune catalytic)
	{
		this.displayName = displayName;
		this.magicLevel = magicLevel;

		Map<ThrallRune, Integer> costs = new EnumMap<>(ThrallRune.class);
		costs.put(elemental, RunesPerCast.ELEMENTAL);
		costs.put(catalytic, RunesPerCast.CATALYTIC);
		costs.put(ThrallRune.COSMIC, RunesPerCast.COSMIC);
		this.runesPerCast = Collections.unmodifiableMap(costs);
	}

	public int getMagicLevel()
	{
		return magicLevel;
	}

	public Map<ThrallRune, Integer> getRunesPerCast()
	{
		return runesPerCast;
	}

	/**
	 * How many thralls of this tier the given rune supply covers, limited by whichever rune runs
	 * out first.
	 */
	public int castsAvailable(ToIntFunction<ThrallRune> availableRunes)
	{
		return runesPerCast.entrySet().stream()
			.mapToInt(cost -> availableRunes.applyAsInt(cost.getKey()) / cost.getValue())
			.min()
			.orElse(0);
	}

	/**
	 * The best tier the given Magic level can cast, falling back to the cheapest tier below the
	 * level requirement of every thrall spell.
	 */
	public static ThrallTier highestCastableAt(int magicLevel)
	{
		return Arrays.stream(values())
			.filter(tier -> magicLevel >= tier.magicLevel)
			.max(Comparator.comparingInt(ThrallTier::getMagicLevel))
			.orElse(LESSER);
	}

	@Override
	public String toString()
	{
		return displayName;
	}
}

package com.confirmspellbook;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.BackgroundComponent;
import net.runelite.client.ui.overlay.components.TextComponent;
import net.runelite.client.util.Text;

@Singleton
public class ConfirmSpellbookOverlay extends Overlay
{
    private static final int PADDING = 6;
    private static final int BUTTON_GAP = 12;
    private static final int BUTTON_INSET = 3;
    private static final String CONFIRM_TEXT = "Confirm";
    private static final BasicStroke BUTTON_BORDER_STROKE = new BasicStroke(0.5f);

    private final Client client;
    private final ConfirmSpellbookPlugin plugin;
    private final ConfirmSpellbookConfig config;

    // Publish bounds and warning identity together, from the renderer to the AWT mouse listener.
    private volatile ConfirmTarget confirmTarget;

    @Inject
    ConfirmSpellbookOverlay(Client client, ConfirmSpellbookPlugin plugin, ConfirmSpellbookConfig config)
    {
        super(plugin);
        this.client = client;
        this.plugin = plugin;
        this.config = config;
        setPosition(OverlayPosition.ABOVE_CHATBOX_RIGHT);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (client.getGameState() != GameState.LOGGED_IN || !plugin.shouldShowWarning())
        {
            clearConfirmTarget();
            return null;
        }

        String displayText = getDisplayText();
        FontMetrics metrics = graphics.getFontMetrics();
        int textWidth = metrics.stringWidth(Text.removeTags(displayText));
        int buttonWidth = metrics.stringWidth(CONFIRM_TEXT) + PADDING * 2;
        int height = metrics.getHeight() + PADDING * 2;
        int buttonX = PADDING + textWidth + BUTTON_GAP;
        boolean showConfirm = plugin.shouldShowConfirmButton();
        int width = showConfirm ? buttonX + buttonWidth + 2 : textWidth + PADDING * 2;

        Color reminderColor = config.reminderColor();
        Color warningColor = config.flashReminderBox() && client.getGameCycle() % 40 >= 20
            ? config.flashColor() : reminderColor;
        BackgroundComponent background = new BackgroundComponent();
        background.setRectangle(new Rectangle(0, 0, width, height));
        background.setBackgroundColor(warningColor);
        background.render(graphics);

        int baseline = PADDING + metrics.getAscent();
        drawText(graphics, displayText, PADDING, baseline, Color.WHITE);
        if (!showConfirm)
        {
            clearConfirmTarget();
            return new Dimension(width, height);
        }

        Rectangle button = new Rectangle(buttonX, BUTTON_INSET, width - buttonX - BUTTON_INSET,
            height - BUTTON_INSET * 2);
        Rectangle canvasButton = new Rectangle(button);
        canvasButton.translate(getBounds().x, getBounds().y);
        net.runelite.api.Point mouse = client.getMouseCanvasPosition();
        boolean hovered = mouse != null && !client.isMenuOpen() && canvasButton.contains(mouse.getX(), mouse.getY());
        // An opaque fill keeps the shared panel's flash from bleeding through the button.
        Color buttonColor = new Color(12 + reminderColor.getRed() / 4, 12 + reminderColor.getGreen() / 4,
            12 + reminderColor.getBlue() / 4);
        graphics.setColor(hovered ? new Color(40, 150, 60) : buttonColor);
        graphics.fillRect(button.x, button.y, button.width, button.height);
        Graphics2D borderGraphics = (Graphics2D) graphics.create();
        try
        {
            borderGraphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            borderGraphics.setStroke(BUTTON_BORDER_STROKE);
            borderGraphics.setColor(Color.WHITE);
            borderGraphics.drawRect(button.x, button.y, button.width - 1, button.height - 1);
        }
        finally
        {
            borderGraphics.dispose();
        }

        drawText(graphics, CONFIRM_TEXT, buttonX + PADDING, baseline, Color.WHITE);
        confirmTarget = new ConfirmTarget(canvasButton, plugin.getWarningVersion());
        return new Dimension(width, height);
    }

    private void drawText(Graphics2D graphics, String text, int x, int y, Color color)
    {
        TextComponent component = new TextComponent();
        component.setText(text);
        component.setPosition(new Point(x, y));
        component.setColor(color);
        component.render(graphics);
    }

    boolean confirmAt(Point point)
    {
        ConfirmTarget target = confirmTarget;
        if (target == null || !plugin.shouldShowWarning()
            || !plugin.shouldShowConfirmButton()
            || client.getGameState() != GameState.LOGGED_IN
            || client.isMenuOpen() || !target.bounds.contains(point))
        {
            return false;
        }

        clearConfirmTarget();
        plugin.confirmWarning(target.warningVersion);
        return true;
    }

    void clearConfirmTarget()
    {
        confirmTarget = null;
    }

    private String getDisplayText()
    {
        switch (config.reminderStyle())
        {
            case CUSTOM_TEXT:
                return config.customText() == null ? "" : config.customText();
            case SHORT_TEXT:
                return plugin.getReminderShortText();
            default:
                return plugin.getReminderLongText();
        }
    }

    private static final class ConfirmTarget
    {
        private final Rectangle bounds;
        private final long warningVersion;

        private ConfirmTarget(Rectangle bounds, long warningVersion)
        {
            this.bounds = bounds;
            this.warningVersion = warningVersion;
        }
    }
}

